/* Momento site styles */
:root {
 --bg: #ffffff;
 --fg: #111827;
 --muted: #6b7280;
 --accent: #2563eb;
 --accent-fg: #ffffff;
 --border: #e5e7eb;
 --panel-bg: #f9fafb;
 --code-bg: #f3f4f6;
 --success: #16a34a;
 --past: #9ca3af;
 --current: #16a34a;
 --upcoming: #2563eb;
}

@media (prefers-color-scheme: dark) {
 :root {
  --bg: #0b0f19;
  --fg: #e5e7eb;
  --muted: #9ca3af;
  --accent: #60a5fa;
  --accent-fg: #0b0f19;
  --border: #374151;
  --panel-bg: #111827;
  --code-bg: #1f2937;
  --success: #22c55e;
  --past: #6b7280;
  --current: #22c55e;
  --upcoming: #93c5fd;
 }
}

body.dark-mode {
 --bg: #0b0f19;
 --fg: #e5e7eb;
 --muted: #9ca3af;
 --accent: #60a5fa;
 --accent-fg: #0b0f19;
 --border: #374151;
 --panel-bg: #111827;
 --code-bg: #1f2937;
 --success: #22c55e;
 --past: #6b7280;
 --current: #22c55e;
 --upcoming: #93c5fd;
}

* {
 box-sizing: border-box;
}

body {
 margin: 0;
 font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
 background: var(--bg);
 color: var(--fg);
 line-height: 1.6;
}

a {
 color: var(--accent);
 text-decoration: none;
}

a:hover {
 text-decoration: underline;
}

header, footer {
 padding: 1rem;
 border-bottom: 1px solid var(--border);
}

footer {
 border-bottom: none;
 border-top: 1px solid var(--border);
}

nav {
 display: flex;
 flex-wrap: wrap;
 gap: 0.75rem;
 align-items: center;
}

nav > p {
 margin: 0;
 color: var(--muted);
 font-size: 0.875rem;
}

main {
 max-width: 800px;
 margin: 0 auto;
 padding: 1rem;
}

.panel {
 background: var(--panel-bg);
 border: 1px solid var(--border);
 border-radius: 0.5rem;
 padding: 1rem;
 margin-bottom: 1rem;
}

.panel h2, .panel h3 {
 margin-top: 0;
}

.panel p {
 margin: 0.5rem 0;
}

.copy-btn {
 background: var(--accent);
 color: var(--accent-fg);
 border: none;
 border-radius: 0.375rem;
 padding: 0.375rem 0.75rem;
 font-size: 0.875rem;
 cursor: pointer;
}

.copy-btn:hover {
 opacity: 0.9;
}

.copy-btn:focus {
 outline: 2px solid var(--accent);
 outline-offset: 2px;
}

.copy-msg {
 margin-left: 0.5rem;
 color: var(--success);
 font-size: 0.875rem;
}

.sr-only {
 position: absolute;
 width: 1px;
 height: 1px;
 padding: 0;
 margin: -1px;
 overflow: hidden;
 clip: rect(0, 0, 0, 0);
 white-space: nowrap;
 border: 0;
}

table {
 width: 100%;
 border-collapse: collapse;
 margin: 0.5rem 0;
}

table th, table td {
 border: 1px solid var(--border);
 padding: 0.5rem;
 text-align: left;
}

table th {
 background: var(--panel-bg);
}

.wake-past {
 color: var(--past);
}

.wake-current {
 color: var(--current);
 font-weight: bold;
}

.wake-upcoming {
 color: var(--upcoming);
}

.local-date-prefix {
 font-size: 0.75rem;
 color: var(--muted);
 margin-right: 0.25rem;
}

pre {
 background: var(--code-bg);
 border-radius: 0.375rem;
 padding: 0.75rem;
 overflow-x: auto;
}

code {
 font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
}

footer p {
 margin: 0.5rem 0;
 text-align: center;
}

@media print {
 header, footer, nav, .copy-btn, .copy-msg, .sr-only, #wake-progress-container {
  display: none !important;
 }
 main {
  max-width: 100%;
  padding: 0;
 }
 .panel {
  break-inside: avoid;
 }
}
